import pandas as pd

def clean(df):
    df = df.copy()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].astype(str).str.replace(',', '', regex=False), errors='coerce')
    df = df.dropna(subset=['body_mass_g'])
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].sum().to_dict()
